from collections import deque
def solve(I):
    H=len(I); W=len(I[0]); bgc=I[0][0]
    lw=next(x for row in I for x in row if x!=bgc)
    def cells_ok(cells): return all(i<0 or i>=H or j<0 or j>=W or I[i][j]==lw for i,j in cells)
    res=[]
    for r0 in range(-1,H+1):
        for c0 in range(-1,W+1):
            for r1 in range(max(0,r0)+2,H+1):
                for c1 in range(max(0,c0)+2,W+1):
                    t=cells_ok([(r0,c) for c in range(c0,c1+1)])
                    b=cells_ok([(r1,c) for c in range(c0,c1+1)])
                    l=cells_ok([(i,c0) for i in range(r0,r1+1)])
                    rr=cells_ok([(i,c1) for i in range(r0,r1+1)])
                    if not(t and b and l and rr): continue
                    if any(I[r][c]==lw for r in range(r0+1,r1) for c in range(c0+1,c1)): continue
                    res.append((r0,r1,c0,c1))
    out=[row[:] for row in I]
    for r0,r1,c0,c1 in res:
        R0,R1=max(0,r0+1),(r1-1 if r1-1>=0 else -1)
        C0,C1=max(0,c0+1),(c1-1 if c1-1>=0 else -1)
        for r in range(R0,R1+1):
            for c in range(C0,C1+1):
                if out[r][c]==bgc: out[r][c]=4
    return out
